/**
 * ensure-dev-data.js — makes `npm run dev` work from a fresh clone.
 *
 * src/data/preloaded-stats.json is generated by prebuild-stats.js and
 * gitignored, but GlobalStats/EBirdStats/GBIFStats import it statically —
 * so on a clean checkout every route 500s in the Vite dev server (the whole
 * module graph fails to resolve, and the page is blank).
 *
 * Runs as the `predev` npm hook: if the file is missing, write an empty-shape
 * stub instantly and offline. The stats components already fall back field by
 * field (`preloaded?.iNaturalist || {}`), so a stub just means the home
 * dashboard fetches live numbers instead of rendering baked ones. Run
 * `node scripts/prebuild-stats.js` for the real thing. An existing file is
 * never touched.
 */

import { existsSync, writeFileSync, mkdirSync } from 'fs'
import { fileURLToPath } from 'url'
import { dirname, join } from 'path'

const __dirname = dirname(fileURLToPath(import.meta.url))
const OUT_DIR = join(__dirname, '..', 'src', 'data')
const OUT_PATH = join(OUT_DIR, 'preloaded-stats.json')

if (!existsSync(OUT_PATH)) {
  mkdirSync(OUT_DIR, { recursive: true })
  writeFileSync(OUT_PATH, JSON.stringify({
    fetchedAt: null,
    allCounts: null,
    iNaturalist: {},
    eBird: {},
    GBIF: {},
  }, null, 2))
  console.log('ensure-dev-data: wrote stub src/data/preloaded-stats.json (fresh clone) — run `node scripts/prebuild-stats.js` to bake real numbers')
}
